svg.script:
// Runs before the app. Works out the folder this SVG lives in, then makes an
// SVG document behave enough like an HTML document for the app to run:
//  - document.createElement returns HTML-namespace elements (an XML/SVG
//    document would otherwise create generic elements with broken inputs).
//  - document.body and document.head point at the HTML parts we embedded.
var __AERO_BASE__ = new URL("./", document.baseURI).pathname;
(function () {
  var shadow = document.implementation.createHTMLDocument("");
  var nativeCreate = shadow.createElement.bind(shadow);
  document.createElement = function (tag, opts) { return nativeCreate(tag, opts); };
  var bodyEl = document.getElementsByTagName("body")[0];
  Object.defineProperty(document, "body", { configurable: true, get: function () { return bodyEl; } });
  Object.defineProperty(document, "head", { configurable: true, get: function () { return document.documentElement; } });
})();
